INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000191',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss climate change at B2","Use advanced Klimawandel vocabulary","Analyse causes and consequences"],"explanation":{"intro":"Advanced climate change vocabulary at B2 covers scientific consensus, policy responses, and climate justice.","culturalNote":"Germany''s Klimaschutzziele (climate protection goals) aim for Klimaneutralität by 2045. The Klimaklage (climate lawsuit) by youth groups (inspired by Fridays for Future) led to a landmark Bundesverfassungsgericht ruling strengthening climate obligations. Key terms: Treibhausgasemissionen (greenhouse gas emissions), Kipppunkte (tipping points), Klimaanpassung (climate adaptation)."},"examples":[{"german":"Die Wissenschaft ist sich einig: Ohne entschlossenes Handeln werden die Kipppunkte des Klimasystems überschritten.","english":"Science is unanimous: without resolute action, the tipping points of the climate system will be crossed."},{"german":"Klimaschutz und wirtschaftliche Entwicklung schließen sich nicht gegenseitig aus.","english":"Climate protection and economic development are not mutually exclusive."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss climate change, tipping points, and climate policy at B2."}}',
'{"items":[{"word":"der Kipppunkt","translation":"tipping point","pronunciation":"dayr KIP-poonkt","example":"Kipppunkte überschreiten."},{"word":"entschlossen","translation":"resolute/determined","pronunciation":"ent-SHLOS-en","example":"Entschlossenes Handeln."},{"word":"überschreiten","translation":"to cross/exceed","pronunciation":"ü-ber-SHRY-ten","example":"Eine Grenze überschreiten."},{"word":"sich einig sein","translation":"to be unanimous/in agreement","pronunciation":"zikh EY-nikh zy","example":"Sich einig sein."},{"word":"gegenseitig","translation":"mutual/reciprocal","pronunciation":"GAY-gen-zy-tikh","example":"Gegenseitig ausschließen."},{"word":"ausschließen","translation":"to exclude/rule out","pronunciation":"OWS-shlee-sen","example":"Sich gegenseitig ausschließen."}]}',
'{"title":"Sich gegenseitig ausschließen — to be mutually exclusive","pattern":"sich gegenseitig ausschließen = to be mutually exclusive (reflexive reciprocal)","explanation":"Sich gegenseitig ausschließen = to be mutually exclusive, to exclude one another. Das schließt sich gegenseitig aus = These are mutually exclusive. Gegenseitig = mutual, reciprocal. Can be used with any reciprocal action: sich gegenseitig helfen (to help each other), sich gegenseitig verstehen (to understand each other). Also: einander (one another — more formal/literary than sich gegenseitig).","examples":[{"sentence":"Qualität und Schnelligkeit schließen sich nicht immer gegenseitig aus.","translation":"Quality and speed do not always exclude one another."},{"sentence":"Diese zwei Ziele schließen sich leider gegenseitig aus.","translation":"These two goals are unfortunately mutually exclusive."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Kipppunkt'' means?","options":["tipping point","breaking point","turning point","threshold"],"correctAnswer":"tipping point"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Science is unanimous: without resolute action, the tipping points of the climate system will be crossed.","options":["Die Wissenschaft ist sich einig: Ohne entschlossenes Handeln werden die Kipppunkte des Klimasystems überschritten.","Wissenschaftler sind sich einig, dass der Klimawandel real ist.","Ohne Handeln werden Klimaziele nicht erreicht.","Die Wissenschaft fordert entschlossenes Handeln."],"correctAnswer":"Die Wissenschaft ist sich einig: Ohne entschlossenes Handeln werden die Kipppunkte des Klimasystems überschritten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Qualität und Schnelligkeit schließen sich nicht immer gegenseitig ___.","options":["aus","ein","ab","weg"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: These two goals are unfortunately mutually exclusive","wordBankItems":["Diese","zwei","Ziele","schließen","sich","leider","gegenseitig","aus","."],"correctAnswer":"Diese zwei Ziele schließen sich leider gegenseitig aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entschlossen'' means?","options":["resolute/determined","decided","concluded","committed"],"correctAnswer":"resolute/determined"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000192',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the Energiewende at B2","Use energy transition vocabulary","Analyse Germany''s energy policy"],"explanation":{"intro":"The Energiewende (energy transition) is Germany''s shift from fossil fuels and nuclear power to renewable energy.","culturalNote":"Germany''s Energiewende aims for 80% renewable electricity by 2030. After Fukushima 2011, Germany decided on the Atomausstieg (nuclear phase-out, completed 2023). The Kohleausstieg (coal phase-out) is set for 2038. Key challenges: Netzausbau (grid expansion), Speicherkapazität (storage capacity), and rising Strompreise (electricity prices). The concept was coined by the Öko-Institut Freiburg in 1980."},"examples":[{"german":"Die Energiewende erfordert nicht nur den Ausbau erneuerbarer Energien, sondern auch grundlegende Veränderungen in der Energieinfrastruktur.","english":"The energy transition requires not only the expansion of renewable energy, but also fundamental changes to energy infrastructure."},{"german":"Der Atomausstieg war eine politische Entscheidung, die bis heute kontrovers diskutiert wird.","english":"The nuclear phase-out was a political decision that continues to be discussed controversially to this day."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s energy transition, policy, and infrastructure at B2."}}',
'{"items":[{"word":"der Atomausstieg","translation":"nuclear phase-out","pronunciation":"dayr AH-tom-ows-steeg","example":"Atomausstieg."},{"word":"der Kohleausstieg","translation":"coal phase-out","pronunciation":"dayr KOH-leh-ows-steeg","example":"Kohleausstieg."},{"word":"der Netzausbau","translation":"grid expansion","pronunciation":"dayr NETS-ows-bow","example":"Netzausbau."},{"word":"die Speicherkapazität","translation":"storage capacity","pronunciation":"dee SHPY-kher-ka-pa-tsee-tät","example":"Speicherkapazität."},{"word":"kontrovers","translation":"controversial","pronunciation":"kon-tro-VERS","example":"Kontrovers diskutiert."},{"word":"der Ausbau","translation":"expansion/development","pronunciation":"dayr OWS-bow","example":"Ausbau erneuerbarer Energien."}]}',
'{"title":"Bis heute — to this day / until now (temporal anchor)","pattern":"bis heute + present or passive = continues to this day, still (formal temporal reference)","explanation":"Bis heute = to this day, until now. Marks that something started in the past and continues into the present. Bis heute gilt... = To this day it applies... bis heute andauern = to continue to this day. Contrast: bis jetzt (up to now — more neutral), bislang (up to now — slightly formal), nach wie vor (still — emphasises despite expectation). Bis heute is often used in historical narratives.","examples":[{"sentence":"Die Debatte wird bis heute geführt.","translation":"The debate continues to this day."},{"sentence":"Bis heute ist die Frage ungeklärt.","translation":"To this day the question is unresolved."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Netzausbau'' means?","options":["grid expansion","network development","power grid","infrastructure expansion"],"correctAnswer":"grid expansion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The nuclear phase-out was a political decision that continues to be discussed controversially to this day.","options":["Der Atomausstieg war eine politische Entscheidung, die bis heute kontrovers diskutiert wird.","Der Atomausstieg ist umstritten.","Deutschland hat den Atomausstieg beschlossen.","Die Entscheidung zum Atomausstieg war politisch."],"correctAnswer":"Der Atomausstieg war eine politische Entscheidung, die bis heute kontrovers diskutiert wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Debatte wird bis heute ___.","options":["geführt","gehalten","betrieben","gepflegt"],"correctAnswer":"geführt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: To this day the question is unresolved","wordBankItems":["Bis","heute","ist","die","Frage","ungeklärt","."],"correctAnswer":"Bis heute ist die Frage ungeklärt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kontrovers'' means?","options":["controversial","debated","conflicting","disputed"],"correctAnswer":"controversial"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000193',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss environmental law at B2","Use Umweltrecht vocabulary","Talk about regulation and compliance"],"explanation":{"intro":"Environmental law vocabulary at B2 covers EU environmental regulation, German law, and enforcement.","culturalNote":"Germany has among the strictest Umweltrecht (environmental law) globally. Key laws: Bundes-Immissionsschutzgesetz (BImSchG — Federal Immission Control Act), Bundesnaturschutzgesetz (Federal Nature Conservation Act), Kreislaufwirtschaftsgesetz (Circular Economy Act). EU Umweltrecht increasingly drives national law. Umwelthaftung (environmental liability) and Verursacherprinzip (polluter pays principle) are core concepts."},"examples":[{"german":"Das Verursacherprinzip besagt, dass derjenige, der Umweltschäden verursacht, auch für deren Behebung verantwortlich ist.","english":"The polluter pays principle states that whoever causes environmental damage is also responsible for remedying it."},{"german":"Die Einhaltung europäischer Umweltstandards ist für alle Mitgliedstaaten verbindlich.","english":"Compliance with European environmental standards is binding for all member states."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss environmental law, the polluter pays principle, and regulatory compliance at B2."}}',
'{"items":[{"word":"das Verursacherprinzip","translation":"polluter pays principle","pronunciation":"dahs fer-OOR-zakh-er-prin-tsip","example":"Verursacherprinzip."},{"word":"verbindlich","translation":"binding/obligatory","pronunciation":"fer-BIND-likh","example":"Verbindliche Standards."},{"word":"die Einhaltung","translation":"compliance/adherence","pronunciation":"dee YN-hal-toong","example":"Einhaltung von Standards."},{"word":"die Behebung","translation":"remedying/rectification","pronunciation":"dee beh-HAY-boong","example":"Behebung von Schäden."},{"word":"besagen","translation":"to state/stipulate","pronunciation":"beh-ZAH-gen","example":"Das Gesetz besagt."},{"word":"die Haftung","translation":"liability","pronunciation":"dee HAF-toong","example":"Umwelthaftung."}]}',
'{"title":"Besagen — to state/stipulate (of laws and rules)","pattern":"etwas besagt, dass + V-final clause = something states/stipulates that (formal legal/doctrinal language)","explanation":"Besagen = to state, stipulate, say (of rules, laws, texts). Das Gesetz besagt, dass... = The law states that... Artikel 1 besagt, dass die Würde unantastbar ist = Article 1 states that dignity is inviolable. More formal than sagen (to say). Compare: lauten (to read, run — of a text): Der Artikel lautet: ... = The article reads: ...; festlegen (to stipulate, set out — more deliberate/prescriptive).","examples":[{"sentence":"Die Regelung besagt, dass alle Teilnehmer eine Genehmigung benötigen.","translation":"The regulation states that all participants require a permit."},{"sentence":"Der Vertrag besagt nichts über Schadensersatz.","translation":"The contract says nothing about damages."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verbindlich'' means?","options":["binding/obligatory","committed","reliable","mandatory"],"correctAnswer":"binding/obligatory"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The polluter pays principle states that whoever causes environmental damage is also responsible for remedying it.","options":["Das Verursacherprinzip besagt, dass derjenige, der Umweltschäden verursacht, auch für deren Behebung verantwortlich ist.","Wer Schäden verursacht, muss sie beheben.","Das Verursacherprinzip macht Verursacher haftbar.","Umweltschäden müssen vom Verursacher behoben werden."],"correctAnswer":"Das Verursacherprinzip besagt, dass derjenige, der Umweltschäden verursacht, auch für deren Behebung verantwortlich ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Regelung besagt, dass alle Teilnehmer eine Genehmigung ___.","options":["benötigen","brauchen","bedürfen","erfordern"],"correctAnswer":"benötigen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The contract says nothing about damages","wordBankItems":["Der","Vertrag","besagt","nichts","über","Schadensersatz","."],"correctAnswer":"Der Vertrag besagt nichts über Schadensersatz ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Einhaltung'' means?","options":["compliance/adherence","holding","keeping","observation"],"correctAnswer":"compliance/adherence"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000194',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss technology policy at B2","Use Technologiepolitik vocabulary","Talk about regulation of emerging tech"],"explanation":{"intro":"Technology policy vocabulary at B2 covers digital regulation, AI governance, and platform regulation.","culturalNote":"Germany and the EU are global leaders in tech regulation. Key legislation: DSGVO (GDPR — data protection), Digital Services Act (DSA), Digital Markets Act (DMA), AI Act (EU AI-Gesetz). Germany''s Digitalstrategie and the concept of Digitale Souveränität (digital sovereignty — not depending on US/Chinese tech platforms) are prominent policy goals."},"examples":[{"german":"Die EU positioniert sich als globaler Regulierungsstandard-Setzer im Bereich der digitalen Wirtschaft.","english":"The EU is positioning itself as a global standard-setter for regulation in the area of the digital economy."},{"german":"Digitale Souveränität bedeutet, dass Europa seine kritische Infrastruktur nicht von ausländischen Technologiekonzernen abhängig machen sollte.","english":"Digital sovereignty means that Europe should not make its critical infrastructure dependent on foreign technology corporations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss technology policy, digital regulation, and digital sovereignty at B2."}}',
'{"items":[{"word":"die Souveränität","translation":"sovereignty","pronunciation":"dee zoo-veh-rä-nee-TÄT","example":"Digitale Souveränität."},{"word":"positionieren","translation":"to position","pronunciation":"po-zi-tsyoh-NEER-en","example":"Sich positionieren als."},{"word":"der Regulierungsstandard","translation":"regulatory standard","pronunciation":"dayr reh-goo-LEER-oonks-shtan-dart","example":"Regulierungsstandard."},{"word":"abhängig machen von","translation":"to make dependent on","pronunciation":"AP-heng-ikh MAH-khen fon","example":"Abhängig machen von."},{"word":"ausländisch","translation":"foreign","pronunciation":"OWS-len-dish","example":"Ausländische Konzerne."},{"word":"der Konzern","translation":"corporation/conglomerate","pronunciation":"dayr kon-TSERN","example":"Technologiekonzerne."}]}',
'{"title":"Sich positionieren als — to position oneself as","pattern":"sich positionieren als + nominative = to position oneself/itself as (strategic framing)","explanation":"Sich positionieren als = to position oneself as. Die EU positioniert sich als Regulierungsführer = The EU positions itself as a regulatory leader. Used for strategic self-description, branding, political framing. Perfect: hat sich positioniert. Die Positionierung = positioning (noun). Also: sich profilieren als (to make one''s mark/profile as — similar but emphasises building a reputation).","examples":[{"sentence":"Das Unternehmen positioniert sich als führender Anbieter nachhaltiger Lösungen.","translation":"The company positions itself as a leading provider of sustainable solutions."},{"sentence":"Deutschland positioniert sich als Innovationsstandort.","translation":"Germany positions itself as a location for innovation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Souveränität'' means?","options":["sovereignty","independence","autonomy","self-determination"],"correctAnswer":"sovereignty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The EU is positioning itself as a global standard-setter for regulation in the area of the digital economy.","options":["Die EU positioniert sich als globaler Regulierungsstandard-Setzer im Bereich der digitalen Wirtschaft.","Die EU reguliert die digitale Wirtschaft.","Die EU setzt globale Digitalstandards.","Die EU ist ein wichtiger Akteur in der digitalen Wirtschaft."],"correctAnswer":"Die EU positioniert sich als globaler Regulierungsstandard-Setzer im Bereich der digitalen Wirtschaft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Unternehmen positioniert sich als führender Anbieter nachhaltiger ___.","options":["Lösungen","Lösung","Angebote","Produkte"],"correctAnswer":"Lösungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Germany positions itself as a location for innovation","wordBankItems":["Deutschland","positioniert","sich","als","Innovationsstandort","."],"correctAnswer":"Deutschland positioniert sich als Innovationsstandort ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausländisch'' means?","options":["foreign","external","international","non-domestic"],"correctAnswer":"foreign"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000195',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss AI and society at B2","Use KI-Gesellschaft vocabulary","Talk about AI ethics and governance"],"explanation":{"intro":"AI and society vocabulary at B2 covers ethical concerns, governance frameworks, and societal impact.","culturalNote":"Künstliche Intelligenz (KI) is reshaping German industry (Industrie 4.0) and society. Key debates: Algorithmic bias (algorithmische Verzerrung), explainable AI (erklärbare KI), Automatisierung und Arbeitsmarkt (automation and labour market), Regulierung (EU AI Act 2024 — world''s first comprehensive AI law). Germany''s AI strategy (Nationale KI-Strategie) aims to be a top AI location."},"examples":[{"german":"Algorithmische Entscheidungssysteme müssen transparent und nachvollziehbar sein, um Diskriminierung zu verhindern.","english":"Algorithmic decision-making systems must be transparent and comprehensible in order to prevent discrimination."},{"german":"Die Frage, wer für Fehler autonomer Systeme haftet, ist juristisch noch nicht abschließend geklärt.","english":"The question of who is liable for errors in autonomous systems has not yet been conclusively clarified in law."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss AI ethics, governance, and societal impact at B2."}}',
'{"items":[{"word":"nachvollziehbar","translation":"comprehensible/traceable","pronunciation":"nakh-FOL-tsee-bar","example":"Nachvollziehbare Entscheidungen."},{"word":"algorithmisch","translation":"algorithmic","pronunciation":"al-go-RITH-mish","example":"Algorithmische Systeme."},{"word":"haften für","translation":"to be liable for","pronunciation":"HAF-ten für","example":"Für Fehler haften."},{"word":"abschließend","translation":"conclusively/finally","pronunciation":"AP-shlee-send","example":"Abschließend geklärt."},{"word":"autonom","translation":"autonomous","pronunciation":"ow-to-NOHM","example":"Autonome Systeme."},{"word":"die Verzerrung","translation":"distortion/bias","pronunciation":"dee fer-TSER-oong","example":"Algorithmische Verzerrung."}]}',
'{"title":"Noch nicht abschließend geklärt — not yet conclusively resolved","pattern":"noch nicht abschließend + Partizip II = not yet conclusively decided/resolved (formal hedge in law/policy)","explanation":"Noch nicht abschließend + past participle = not yet conclusively resolved. Common in legal and policy language: noch nicht abschließend geklärt (not yet conclusively clarified), noch nicht abschließend entschieden (not yet conclusively decided), noch nicht abschließend geregelt (not yet conclusively regulated). The adverb abschließend (conclusively, finally) qualifies the state as still open. Compare: offen (open — simpler), ungeklärt (unresolved — plainer).","examples":[{"sentence":"Diese Rechtsfrage ist noch nicht abschließend entschieden.","translation":"This legal question has not yet been conclusively decided."},{"sentence":"Viele Aspekte der KI-Regulierung sind noch nicht abschließend geregelt.","translation":"Many aspects of AI regulation are not yet conclusively settled."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Nachvollziehbar'' means?","options":["comprehensible/traceable","understandable","transparent","verifiable"],"correctAnswer":"comprehensible/traceable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Algorithmic decision-making systems must be transparent and comprehensible in order to prevent discrimination.","options":["Algorithmische Entscheidungssysteme müssen transparent und nachvollziehbar sein, um Diskriminierung zu verhindern.","KI-Systeme sollen keine Diskriminierung verursachen.","Transparenz verhindert Diskriminierung in KI.","KI-Entscheidungen müssen erklärbar sein."],"correctAnswer":"Algorithmische Entscheidungssysteme müssen transparent und nachvollziehbar sein, um Diskriminierung zu verhindern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Rechtsfrage ist noch nicht abschließend ___.","options":["entschieden","entschieden worden","zu entscheiden","entschieden sein"],"correctAnswer":"entschieden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Many aspects of AI regulation are not yet conclusively settled","wordBankItems":["Viele","Aspekte","der","KI-Regulierung","sind","noch","nicht","abschließend","geregelt","."],"correctAnswer":"Viele Aspekte der KI-Regulierung sind noch nicht abschließend geregelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Haften für'' means?","options":["to be liable for","to hold to","to stick to","to be responsible for"],"correctAnswer":"to be liable for"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000196',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss data protection at B2","Use DSGVO vocabulary","Talk about privacy rights and obligations"],"explanation":{"intro":"Data protection vocabulary at B2 covers GDPR, data subject rights, and corporate obligations.","culturalNote":"Germany has a long tradition of Datenschutz (data protection) — the world''s first data protection law was passed in Hessen in 1970. The DSGVO (Datenschutz-Grundverordnung = GDPR) applies EU-wide since 2018. Key rights: Auskunftsrecht (right of access), Recht auf Vergessenwerden (right to be forgotten), Datenportabilität (data portability). Violations can result in fines up to 4% of global turnover."},"examples":[{"german":"Personenbezogene Daten dürfen nur mit ausdrücklicher Einwilligung der Betroffenen oder auf einer gesetzlichen Grundlage verarbeitet werden.","english":"Personal data may only be processed with the explicit consent of those concerned or on a legal basis."},{"german":"Das Recht auf Vergessenwerden ermöglicht es Personen, unter bestimmten Umständen die Löschung ihrer Daten zu verlangen.","english":"The right to be forgotten enables persons to demand the deletion of their data under certain circumstances."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss GDPR, data subject rights, and data protection obligations at B2."}}',
'{"items":[{"word":"personenbezogen","translation":"personal (relating to a person)","pronunciation":"per-ZOH-nen-beh-tso-gen","example":"Personenbezogene Daten."},{"word":"die Einwilligung","translation":"consent","pronunciation":"dee YN-vil-ee-goong","example":"Ausdrückliche Einwilligung."},{"word":"ausdrücklich","translation":"explicit/express","pronunciation":"OWS-drük-likh","example":"Ausdrücklich erteilen."},{"word":"verarbeiten","translation":"to process (data)","pronunciation":"fer-AR-by-ten","example":"Daten verarbeiten."},{"word":"die Löschung","translation":"deletion/erasure","pronunciation":"dee LÖ-shoong","example":"Löschung der Daten."},{"word":"verlangen","translation":"to demand/require","pronunciation":"fer-LANG-en","example":"Löschung verlangen."}]}',
'{"title":"Dürfen nur... oder auf Grundlage — may only... or on the basis of","pattern":"etwas darf nur + infinitive + unter Bedingung (may only be done under condition — legal permission structure)","explanation":"Legal permission structure: dürfen nur + Infinitiv (Passiv) = may only be (done). Daten dürfen nur verarbeitet werden, wenn... = Data may only be processed when... The modal dürfen expresses what is allowed. Nur restricts scope. Auf einer gesetzlichen Grundlage = on a legal basis (legal phrase). Pattern: darf nur + Partizip II + werden + Condition.","examples":[{"sentence":"Medikamente dürfen nur auf Rezept abgegeben werden.","translation":"Medicines may only be dispensed on prescription."},{"sentence":"Der Zugang darf nur mit gültiger Genehmigung gewährt werden.","translation":"Access may only be granted with a valid permit."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausdrücklich'' means?","options":["explicit/express","specifically","clearly","intentionally"],"correctAnswer":"explicit/express"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Personal data may only be processed with the explicit consent of those concerned or on a legal basis.","options":["Personenbezogene Daten dürfen nur mit ausdrücklicher Einwilligung der Betroffenen oder auf einer gesetzlichen Grundlage verarbeitet werden.","Personendaten brauchen Einwilligung.","Daten dürfen nur mit Erlaubnis verarbeitet werden.","Ohne Einwilligung dürfen keine Daten verarbeitet werden."],"correctAnswer":"Personenbezogene Daten dürfen nur mit ausdrücklicher Einwilligung der Betroffenen oder auf einer gesetzlichen Grundlage verarbeitet werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Medikamente dürfen nur auf Rezept ___.","options":["abgegeben werden","abgegeben sein","abzugeben sein","abgegeben"],"correctAnswer":"abgegeben werden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Access may only be granted with a valid permit","wordBankItems":["Der","Zugang","darf","nur","mit","gültiger","Genehmigung","gewährt","werden","."],"correctAnswer":"Der Zugang darf nur mit gültiger Genehmigung gewährt werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Löschung'' in data protection means?","options":["deletion/erasure","cancellation","removal","clearing"],"correctAnswer":"deletion/erasure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000197',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media at B2","Use B2 media vocabulary","Talk about journalism, media bias, and press freedom"],"explanation":{"intro":"Media vocabulary at B2 covers press freedom, media landscape, and information quality.","culturalNote":"Germany has a diverse Medienlandschaft (media landscape): ARD and ZDF (public broadcasters), hundreds of Tageszeitungen (daily newspapers), and large private broadcasters. Press freedom (Pressefreiheit) is guaranteed in Article 5 GG. Germany ranks around 10th globally for press freedom. Key issues: Lokalzeitungssterben (death of local papers), Medienbias (media bias), and Desinformation. The Presserat (Press Council) is the self-regulatory body."},"examples":[{"german":"Eine freie und unabhängige Presse ist eine der wichtigsten Säulen der Demokratie.","english":"A free and independent press is one of the most important pillars of democracy."},{"german":"Mit der Digitalisierung hat sich die Medienlandschaft tiefgreifend verändert, und neue Herausforderungen für den Qualitätsjournalismus sind entstanden.","english":"With digitalisation, the media landscape has changed profoundly, and new challenges for quality journalism have emerged."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss media, press freedom, and journalism challenges at B2."}}',
'{"items":[{"word":"die Säule","translation":"pillar/column","pronunciation":"dee ZOY-leh","example":"Säulen der Demokratie."},{"word":"unabhängig","translation":"independent","pronunciation":"OON-ap-heng-ikh","example":"Unabhängige Presse."},{"word":"entstehen","translation":"to emerge/arise","pronunciation":"ent-SHTAY-en","example":"Neue Herausforderungen entstehen."},{"word":"die Desinformation","translation":"disinformation","pronunciation":"dee dez-in-for-MAH-tsyohn","example":"Desinformation bekämpfen."},{"word":"der Qualitätsjournalismus","translation":"quality journalism","pronunciation":"dayr kva-lee-TÄTS-jour-nah-lis-moos","example":"Qualitätsjournalismus."},{"word":"die Medienlandschaft","translation":"media landscape","pronunciation":"dee MEH-dee-en-lant-shaft","example":"Medienlandschaft."}]}',
'{"title":"Entstanden sein — to have emerged (stative perfect)","pattern":"etwas ist entstanden = something has emerged, arisen (sein-perfect of entstehen)","explanation":"Entstehen (to emerge, arise, originate) forms perfect with sein: ist entstanden. New challenges have emerged = Neue Herausforderungen sind entstanden. Also: ein Problem ist entstanden (a problem has arisen). Compare: ergeben sich (to arise, result — reflexive), aufkommen (to arise, come up), auftreten (to appear, occur — of problems/symptoms). Entstehung = origin, emergence (noun).","examples":[{"sentence":"Durch die Digitalisierung sind neue Berufsbilder entstanden.","translation":"Through digitalisation, new job profiles have emerged."},{"sentence":"Ein Missverständnis ist entstanden.","translation":"A misunderstanding has arisen."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Säule'' in ''Säulen der Demokratie'' means?","options":["pillar/column","foundation","cornerstone","base"],"correctAnswer":"pillar/column"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A free and independent press is one of the most important pillars of democracy.","options":["Eine freie und unabhängige Presse ist eine der wichtigsten Säulen der Demokratie.","Pressefreiheit ist für die Demokratie wichtig.","Eine unabhängige Presse stärkt die Demokratie.","Die Demokratie braucht eine freie Presse."],"correctAnswer":"Eine freie und unabhängige Presse ist eine der wichtigsten Säulen der Demokratie."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Durch die Digitalisierung sind neue Berufsbilder ___.","options":["entstanden","entstanden sind","entstehen","entstanden haben"],"correctAnswer":"entstanden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A misunderstanding has arisen","wordBankItems":["Ein","Missverständnis","ist","entstanden","."],"correctAnswer":"Ein Missverständnis ist entstanden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entstehen'' forms its perfect with which auxiliary?","options":["sein","haben","werden","both"],"correctAnswer":"sein"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000198',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss public discourse at B2","Use öffentlicher Diskurs vocabulary","Talk about debate culture"],"explanation":{"intro":"Public discourse vocabulary at B2 covers civil debate, deliberative democracy, and discourse norms.","culturalNote":"Germany has a strong tradition of Streitkultur (culture of debate) and Diskursethik (discourse ethics — Jürgen Habermas). The Öffentlichkeit (public sphere) concept (also Habermas) describes the arena where citizens discuss and form opinion. Populismus (populism), Polarisierung (polarisation), and Echo-Kammern (echo chambers) are threats to healthy public discourse. Talkshows and Talkshow-Demokratie are cultural phenomena."},"examples":[{"german":"Eine funktionierende Demokratie braucht einen offenen und sachlichen öffentlichen Diskurs.","english":"A functioning democracy needs an open and factual public discourse."},{"german":"Polarisierung und Echo-Kammern erschweren den konstruktiven Austausch unterschiedlicher Meinungen.","english":"Polarisation and echo chambers make the constructive exchange of different opinions more difficult."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss public discourse, deliberation, and communication at B2."}}',
'{"items":[{"word":"sachlich","translation":"factual/objective","pronunciation":"ZAKH-likh","example":"Sachliche Debatte."},{"word":"die Polarisierung","translation":"polarisation","pronunciation":"dee po-lah-ree-TSEE-roong","example":"Gesellschaftliche Polarisierung."},{"word":"erschwerren","translation":"to make more difficult","pronunciation":"er-SHVER-en","example":"Den Austausch erschweren."},{"word":"konstruktiv","translation":"constructive","pronunciation":"kon-strook-TEEF","example":"Konstruktiver Austausch."},{"word":"der Austausch","translation":"exchange/interchange","pronunciation":"dayr OWS-towsh","example":"Austausch von Meinungen."},{"word":"die Echo-Kammer","translation":"echo chamber","pronunciation":"dee EH-kho-kam-er","example":"Echo-Kammern."}]}',
'{"title":"Erschweren — to make more difficult (causative)","pattern":"etwas erschwert etwas = something makes something more difficult (no reflexive needed)","explanation":"Erschweren = to make more difficult, complicate. Takes accusative: die Situation erschwert die Lösung = the situation makes the solution more difficult. Die Erschwernis = difficulty, complication (noun). Compare: erleichtern (to facilitate, make easier — opposite), behindern (to hinder/obstruct — stronger), verkomplizieren (to complicate — more colloquial). Erschwerend kommt hinzu, dass... = making it harder, there is also the fact that... (formula for stacking difficulties).","examples":[{"sentence":"Die schlechten Wetterbedingungen erschwerten die Rettungsarbeiten erheblich.","translation":"The poor weather conditions considerably hampered the rescue work."},{"sentence":"Erschwerend kommt hinzu, dass keine Reserven vorhanden sind.","translation":"Making things harder, there are also no reserves available."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sachlich'' means?","options":["factual/objective","factual","matter-of-fact","neutral"],"correctAnswer":"factual/objective"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Polarisation and echo chambers make the constructive exchange of different opinions more difficult.","options":["Polarisierung und Echo-Kammern erschweren den konstruktiven Austausch unterschiedlicher Meinungen.","Durch Polarisierung und Echo-Kammern wird Austausch schwieriger.","Echo-Kammern und Polarisierung sind schlecht für den Diskurs.","Konstruktiver Austausch ist durch Polarisierung gefährdet."],"correctAnswer":"Polarisierung und Echo-Kammern erschweren den konstruktiven Austausch unterschiedlicher Meinungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die schlechten Wetterbedingungen erschwerten die Rettungsarbeiten ___.","options":["erheblich","stark","sehr","bedeutend"],"correctAnswer":"erheblich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Making things harder, there are also no reserves available","wordBankItems":["Erschwerend","kommt","hinzu",",","dass","keine","Reserven","vorhanden","sind","."],"correctAnswer":"Erschwerend kommt hinzu , dass keine Reserven vorhanden sind ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Konstruktiv'' means?","options":["constructive","structural","building","helpful"],"correctAnswer":"constructive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000199',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss rhetoric at B2","Use Rhetorik vocabulary","Identify rhetorical devices in German"],"explanation":{"intro":"Rhetoric vocabulary at B2 covers classical rhetorical devices and persuasion techniques.","culturalNote":"Classical rhetoric (Cicero, Aristotle) is taught in German Gymnasien. Key rhetorical concepts: Ethos (credibility), Pathos (emotion), Logos (logic). Rhetorical devices: Metapher (metaphor), Ironie (irony), Hyperbel (hyperbole), Anapher (anaphora), Parallelismus (parallelism). Political rhetoric analysis is part of German media literacy education."},"examples":[{"german":"Durch die Verwendung von Metaphern macht der Redner abstrakte Konzepte greifbarer und überzeugender.","english":"Through the use of metaphors, the speaker makes abstract concepts more tangible and persuasive."},{"german":"Die Anapher — die Wiederholung eines Ausdrucks am Satzanfang — verleiht Reden Nachdruck und Struktur.","english":"The anaphora — the repetition of an expression at the start of a sentence — lends speeches emphasis and structure."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss rhetorical devices, persuasion, and speech analysis at B2."}}',
'{"items":[{"word":"die Metapher","translation":"metaphor","pronunciation":"dee meh-TAH-fer","example":"Metaphern verwenden."},{"word":"die Anapher","translation":"anaphora","pronunciation":"dee ah-NAH-fer","example":"Anapher."},{"word":"greifbar","translation":"tangible/concrete","pronunciation":"GRYF-bar","example":"Greifbar machen."},{"word":"überzeugend","translation":"persuasive/convincing","pronunciation":"ü-ber-TSOY-gend","example":"Überzeugend argumentieren."},{"word":"verleihen","translation":"to lend/confer","pronunciation":"fer-LY-en","example":"Nachdruck verleihen."},{"word":"der Nachdruck","translation":"emphasis","pronunciation":"dayr NAKH-drook","example":"Mit Nachdruck."}]}',
'{"title":"Verleihen — to lend/confer (rhetorical/formal)","pattern":"etwas verleiht etwas + dative = something lends/confers something to something (formal, often style/quality)","explanation":"Verleihen = to lend, confer, bestow (more formal than geben). Die Metapher verleiht dem Text Kraft = The metaphor lends the text power. Einer Rede Nachdruck verleihen = to lend a speech emphasis. Pattern: verleiht + [what is conferred, accusative] + [to whom, dative]. Perfect: hat verliehen. Also: einen Preis verleihen (to award a prize), eine Auszeichnung verleihen (to confer an award).","examples":[{"sentence":"Das Gedicht verleiht dem Alltäglichen eine besondere Tiefe.","translation":"The poem lends the everyday a special depth."},{"sentence":"Diese Erfahrung hat ihm eine neue Perspektive verliehen.","translation":"This experience has lent him a new perspective."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Greifbar'' means?","options":["tangible/concrete","graspable","accessible","reachable"],"correctAnswer":"tangible/concrete"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Through the use of metaphors, the speaker makes abstract concepts more tangible and persuasive.","options":["Durch die Verwendung von Metaphern macht der Redner abstrakte Konzepte greifbarer und überzeugender.","Metaphern helfen dabei, Abstraktes zu erklären.","Der Redner benutzt Metaphern für bessere Überzeugung.","Mit Metaphern werden abstrakte Ideen verständlicher."],"correctAnswer":"Durch die Verwendung von Metaphern macht der Redner abstrakte Konzepte greifbarer und überzeugender."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gedicht verleiht dem Alltäglichen eine besondere ___.","options":["Tiefe","Bedeutung","Qualität","Dimension"],"correctAnswer":"Tiefe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This experience has lent him a new perspective","wordBankItems":["Diese","Erfahrung","hat","ihm","eine","neue","Perspektive","verliehen","."],"correctAnswer":"Diese Erfahrung hat ihm eine neue Perspektive verliehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überzeugend'' means?","options":["persuasive/convincing","sure","decisive","compelling"],"correctAnswer":"persuasive/convincing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss argumentation at B2","Use Argumentation vocabulary","Structure arguments formally"],"explanation":{"intro":"Argumentation vocabulary at B2 covers formal argument structure, premises, and logical reasoning.","culturalNote":"German academic and professional culture values structured argumentation (Erörterung). The Erörterung (essay/argumentation) is a school genre: Einleitung (introduction), Hauptteil (body — pro and contra), Schluss (conclusion). Key concepts: These (thesis), Antithese (antithesis), Synthese (synthesis) — the Hegelian triad is well-known in German discourse."},"examples":[{"german":"Eine überzeugende Argumentation setzt eine klar formulierte These, stichhaltige Belege und eine logische Schlussfolgerung voraus.","english":"A convincing argumentation presupposes a clearly formulated thesis, sound evidence, and a logical conclusion."},{"german":"Wer argumentiert, muss bereit sein, die eigene These zu überdenken, wenn die Gegenargumente stichhaltig sind.","english":"Whoever argues must be willing to reconsider their own thesis if the counter-arguments are sound."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can structure and discuss formal argumentation at B2."}}',
'{"items":[{"word":"die These","translation":"thesis","pronunciation":"dee TAY-zeh","example":"Eine These aufstellen."},{"word":"stichhaltig","translation":"sound/compelling (of arguments)","pronunciation":"SHTIKH-hal-tikh","example":"Stichhaltige Belege."},{"word":"die Schlussfolgerung","translation":"conclusion/inference","pronunciation":"dee SHLOOSS-fol-geh-roong","example":"Eine Schlussfolgerung ziehen."},{"word":"das Gegenargument","translation":"counter-argument","pronunciation":"dahs GAY-gen-ar-goo-ment","example":"Gegenargumente."},{"word":"der Beleg","translation":"evidence/proof","pronunciation":"dayr beh-LEHG","example":"Belege anführen."},{"word":"die Erörterung","translation":"formal essay/argumentation","pronunciation":"dee er-ÖR-teh-roong","example":"Erörterung schreiben."}]}',
'{"title":"Voraussetzen — to presuppose/require (abstract conditions)","pattern":"etwas setzt etwas voraus = something presupposes/requires something as a precondition (separable)","explanation":"Voraussetzen (separable) = to presuppose, require as a precondition. Eine überzeugende Argumentation setzt eine klare These voraus = A convincing argumentation requires a clear thesis. Perfect: hat vorausgesetzt. Die Voraussetzung = the presupposition/prerequisite. Setzt...voraus is used when something is an implicit necessary condition — stronger than brauchen (to need) or erfordern (to require — more active effort required).","examples":[{"sentence":"Dieses Studium setzt sehr gute Deutschkenntnisse voraus.","translation":"This degree programme requires very good German language skills."},{"sentence":"Vertrauen setzt Ehrlichkeit voraus.","translation":"Trust presupposes honesty."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Stichhaltig'' means?","options":["sound/compelling (of arguments)","piercing","sharp","substantial"],"correctAnswer":"sound/compelling (of arguments)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A convincing argumentation presupposes a clearly formulated thesis, sound evidence, and a logical conclusion.","options":["Eine überzeugende Argumentation setzt eine klar formulierte These, stichhaltige Belege und eine logische Schlussfolgerung voraus.","Eine gute Argumentation braucht eine These und Belege.","Für eine überzeugende Argumentation sind Belege wichtig.","Argumentation besteht aus These, Belegen und Schluss."],"correctAnswer":"Eine überzeugende Argumentation setzt eine klar formulierte These, stichhaltige Belege und eine logische Schlussfolgerung voraus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dieses Studium setzt sehr gute Deutschkenntnisse ___.","options":["voraus","voraussetzt","aus","ein"],"correctAnswer":"voraus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust presupposes honesty","wordBankItems":["Vertrauen","setzt","Ehrlichkeit","voraus","."],"correctAnswer":"Vertrauen setzt Ehrlichkeit voraus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Schlussfolgerung'' means?","options":["conclusion/inference","final argument","closing statement","logical end"],"correctAnswer":"conclusion/inference"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019b',1,'APPROVED','PUBLISHED',
'{"objectives":["Conduct a debate at B2","Use Debatte language","Handle opposition and concessions"],"explanation":{"intro":"Debate language at B2 equips you to argue, concede, challenge, and summarise positions in formal debate.","culturalNote":"German debate culture values Sachlichkeit (objectivity) and structured argument. Parliamentary debate (Bundestagsdebatte) follows strict rules. Common debate phrases: Ich stimme Ihnen zu, dass... (I agree with you that...), Ich widerspreche der Auffassung, dass... (I contradict the view that...), Einzuräumen ist, dass... (It must be conceded that...)."},"examples":[{"german":"Ich widerspreche der These, dass Wirtschaftswachstum automatisch zu mehr Wohlstand führt.","english":"I contradict the thesis that economic growth automatically leads to more prosperity."},{"german":"Einzuräumen ist, dass das Argument durchaus Berechtigung hat, jedoch greift es zu kurz.","english":"It must be conceded that the argument certainly has justification, but it falls short."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can argue, concede, and challenge positions in formal German debate at B2."}}',
'{"items":[{"word":"widersprechen","translation":"to contradict/object to","pronunciation":"VEE-der-shprekh-en","example":"Der These widersprechen."},{"word":"einräumen","translation":"to concede/admit","pronunciation":"YN-roy-men","example":"Einzuräumen ist."},{"word":"die Berechtigung","translation":"justification/validity","pronunciation":"dee beh-REKH-tee-goong","example":"Berechtigung haben."},{"word":"zu kurz greifen","translation":"to fall short/be insufficient","pronunciation":"tsoo koorts GRY-fen","example":"Zu kurz greifen."},{"word":"durchaus","translation":"certainly/quite","pronunciation":"doorhh-OWS","example":"Durchaus berechtigt."},{"word":"die Auffassung","translation":"view/understanding","pronunciation":"dee OWF-fas-oong","example":"Der Auffassung sein."}]}',
'{"title":"Einzuräumen ist, dass — it must be conceded that (formal concession)","pattern":"Einzuräumen ist, dass + V-final clause = It must be conceded/admitted that (elevated concession formula)","explanation":"Einzuräumen ist, dass... = It must be conceded that, I must admit that. The infinitive einzuräumen is fronted (nominalized infinitive construction). It signals a concession before countering. Common in formal debate and academic writing. Similar: Zugegeben, dass... (I grant that...), Zuzugeben ist allerdings, dass... (It must be granted, however, that...), Freilich... (certainly/admittedly — concessive adverb).","examples":[{"sentence":"Einzuräumen ist, dass die Gegenseite einige valide Punkte angeführt hat.","translation":"It must be conceded that the other side has raised some valid points."},{"sentence":"Zugegeben, die Kosten sind hoch — aber die langfristigen Vorteile überwiegen.","translation":"Admittedly, the costs are high — but the long-term benefits outweigh them."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Durchaus'' means?","options":["certainly/quite","absolutely","by all means","thoroughly"],"correctAnswer":"certainly/quite"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I contradict the thesis that economic growth automatically leads to more prosperity.","options":["Ich widerspreche der These, dass Wirtschaftswachstum automatisch zu mehr Wohlstand führt.","Wirtschaftswachstum führt nicht automatisch zu Wohlstand.","Ich bin anderer Meinung über Wirtschaftswachstum.","Nicht jedes Wachstum führt zu Wohlstand."],"correctAnswer":"Ich widerspreche der These, dass Wirtschaftswachstum automatisch zu mehr Wohlstand führt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Einzuräumen ist, dass die Gegenseite einige valide Punkte ___.","options":["angeführt hat","angeführt","geführt","führte"],"correctAnswer":"angeführt hat"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Admittedly, the costs are high — but the long-term benefits outweigh them","wordBankItems":["Zugegeben",",","die","Kosten","sind","hoch","—","aber","die","langfristigen","Vorteile","überwiegen","."],"correctAnswer":"Zugegeben , die Kosten sind hoch — aber die langfristigen Vorteile überwiegen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zu kurz greifen'' means?","options":["to fall short/be insufficient","to grasp too little","to miss the point","to underestimate"],"correctAnswer":"to fall short/be insufficient"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019c',1,'APPROVED','PUBLISHED',
'{"objectives":["Conduct a negotiation at B2","Use Verhandlung language","Make proposals and compromises formally"],"explanation":{"intro":"Negotiation language at B2 covers making proposals, seeking compromise, and handling disagreement formally.","culturalNote":"German business and political negotiation culture values Sachlichkeit (objectivity), Verlässlichkeit (reliability), and written agreements. Key negotiation phrases: einen Kompromiss anstreben (to aim for a compromise), Zugeständnisse machen (to make concessions), auf Einwände eingehen (to address objections)."},"examples":[{"german":"Um eine für beide Seiten akzeptable Lösung zu finden, sind gegenseitige Zugeständnisse unerlässlich.","english":"In order to find a solution acceptable to both sides, mutual concessions are indispensable."},{"german":"Wir sind bereit, über die Bedingungen zu verhandeln, sofern die Kernpunkte unserer Position respektiert werden.","english":"We are prepared to negotiate about the conditions, provided that the key points of our position are respected."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can use formal negotiation language to make proposals, concessions, and compromises at B2."}}',
'{"items":[{"word":"das Zugeständnis","translation":"concession","pronunciation":"dahs TSOO-geh-shtänt-nis","example":"Zugeständnisse machen."},{"word":"unerlässlich","translation":"indispensable/essential","pronunciation":"OON-er-läs-likh","example":"Unerlässlich sein."},{"word":"die Kernpunkte","translation":"key points","pronunciation":"dee KERN-poonk-teh","example":"Kernpunkte der Position."},{"word":"respektieren","translation":"to respect","pronunciation":"reh-spek-TEER-en","example":"Standpunkte respektieren."},{"word":"anstreben","translation":"to aim for/strive for","pronunciation":"AN-shtray-ben","example":"Einen Kompromiss anstreben."},{"word":"eingehen auf","translation":"to address/respond to","pronunciation":"YN-gay-en owf","example":"Auf Einwände eingehen."}]}',
'{"title":"Sofern — provided that (formal conditional)","pattern":"sofern + V-final clause (provided that — formal conditional, implies stricter condition than wenn)","explanation":"Sofern = provided that, as long as (formal). Stricter and more conditional than wenn. Wir verhandeln, sofern die Bedingungen stimmen = We negotiate, provided (that) the conditions are right. Pattern: sofern + V-final clause. More formal than wenn. Also conditional in if-then logic: Sofern keine neuen Informationen vorliegen... = Provided no new information is available... Compare: vorausgesetzt dass (presupposing that — even more formal), falls (if, emphasising possibility).","examples":[{"sentence":"Wir stimmen zu, sofern die Frist verlängert wird.","translation":"We agree, provided that the deadline is extended."},{"sentence":"Das Projekt startet sofern die Finanzierung gesichert ist.","translation":"The project starts provided that funding is secured."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unerlässlich'' means?","options":["indispensable/essential","unavoidable","necessary","obligatory"],"correctAnswer":"indispensable/essential"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In order to find a solution acceptable to both sides, mutual concessions are indispensable.","options":["Um eine für beide Seiten akzeptable Lösung zu finden, sind gegenseitige Zugeständnisse unerlässlich.","Beide Seiten müssen Kompromisse eingehen.","Gegenseitige Zugeständnisse führen zu einer Lösung.","Für eine gemeinsame Lösung sind Kompromisse nötig."],"correctAnswer":"Um eine für beide Seiten akzeptable Lösung zu finden, sind gegenseitige Zugeständnisse unerlässlich."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir stimmen zu, sofern die Frist ___ wird.","options":["verlängert","verlängert worden","zu verlängern","verlängernd"],"correctAnswer":"verlängert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project starts provided that funding is secured","wordBankItems":["Das","Projekt","startet","sofern","die","Finanzierung","gesichert","ist","."],"correctAnswer":"Das Projekt startet sofern die Finanzierung gesichert ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sofern'' is which type of conjunction?","options":["subordinating (V-final)","coordinating (V2)","concessive","causal"],"correctAnswer":"subordinating (V-final)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019d',1,'APPROVED','PUBLISHED',
'{"objectives":["Give a presentation at B2","Use Präsentation language","Structure and deliver formal presentations"],"explanation":{"intro":"Presentation language at B2 covers structuring, signposting, and delivering formal German presentations.","culturalNote":"German presentations tend to be structured, detail-oriented, and thorough. Key signposting phrases: Im Folgenden werde ich... (In the following I will...), Ich komme nun zu... (I now come to...), Abschließend möchte ich... (In conclusion I would like to...), Um das Gesagte zusammenzufassen... (To summarise what has been said...)."},"examples":[{"german":"Im Folgenden werde ich die wichtigsten Ergebnisse unserer Analyse vorstellen und anschließend mögliche Handlungsoptionen skizzieren.","english":"In the following, I will present the most important results of our analysis and subsequently outline possible courses of action."},{"german":"Bevor ich zum zweiten Punkt übergehe, möchte ich kurz auf eine häufig gestellte Frage eingehen.","english":"Before I move on to the second point, I would like to briefly address a frequently asked question."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can structure and deliver formal presentations in German at B2."}}',
'{"items":[{"word":"skizzieren","translation":"to outline/sketch","pronunciation":"ski-TSEER-en","example":"Handlungsoptionen skizzieren."},{"word":"anschließend","translation":"subsequently/then","pronunciation":"AN-shlee-send","example":"Anschließend besprechen."},{"word":"übergehen zu","translation":"to move on to","pronunciation":"ü-ber-GAY-en tsoo","example":"Zum nächsten Punkt übergehen."},{"word":"im Folgenden","translation":"in the following","pronunciation":"im FOL-gen-den","example":"Im Folgenden werde ich."},{"word":"die Handlungsoption","translation":"course of action","pronunciation":"dee HANT-loonks-op-tsyohn","example":"Handlungsoptionen."},{"word":"eingehen auf","translation":"to address/deal with","pronunciation":"YN-gay-en owf","example":"Auf eine Frage eingehen."}]}',
'{"title":"Im Folgenden werde ich — signposting future content in presentations","pattern":"Im Folgenden werde ich + Infinitiv = In the following I will (introduce, show, discuss...)","explanation":"Im Folgenden = in the following (formal temporal/structural signal). Im Folgenden werde ich... is the standard opener for a German presentation body. Pattern: Im Folgenden werde ich [X] [vorstellen/zeigen/erläutern/besprechen]. Equivalent: Zunächst werde ich... (First, I will...), Danach werde ich... (After that, I will...), Abschließend werde ich... (Finally, I will...). These signposting phrases are essential for coherent formal German presentations.","examples":[{"sentence":"Im Folgenden werde ich auf drei Aspekte eingehen.","translation":"In the following I will address three aspects."},{"sentence":"Zunächst werde ich den Kontext erläutern, dann die Ergebnisse vorstellen.","translation":"First I will explain the context, then present the results."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Skizzieren'' means?","options":["to outline/sketch","to sketch","to draft","to summarise"],"correctAnswer":"to outline/sketch"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In the following, I will present the most important results of our analysis and subsequently outline possible courses of action.","options":["Im Folgenden werde ich die wichtigsten Ergebnisse unserer Analyse vorstellen und anschließend mögliche Handlungsoptionen skizzieren.","Ich stelle die Ergebnisse vor und dann die Handlungsoptionen.","Unsere Analyse zeigt wichtige Ergebnisse und Optionen.","Ich werde die Ergebnisse und Optionen zeigen."],"correctAnswer":"Im Folgenden werde ich die wichtigsten Ergebnisse unserer Analyse vorstellen und anschließend mögliche Handlungsoptionen skizzieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Folgenden werde ich auf drei Aspekte ___.","options":["eingehen","ansprechen","erläutern","behandeln"],"correctAnswer":"eingehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: First I will explain the context then present the results","wordBankItems":["Zunächst","werde","ich","den","Kontext","erläutern",",","dann","die","Ergebnisse","vorstellen","."],"correctAnswer":"Zunächst werde ich den Kontext erläutern , dann die Ergebnisse vorstellen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anschließend'' means?","options":["subsequently/then","finally","next","following that"],"correctAnswer":"subsequently/then"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019e',1,'APPROVED','PUBLISHED',
'{"objectives":["Write formally at B2","Use schriftliche Kommunikation vocabulary","Produce formal written German"],"explanation":{"intro":"Written communication vocabulary at B2 covers formal letters, reports, and official documents.","culturalNote":"Formal German written communication follows strict conventions. Key formulas: Sehr geehrte Damen und Herren (Dear Sir or Madam), Mit freundlichen Grüßen (Yours sincerely), Bezüglich Ihres Schreibens vom... (Regarding your letter of...), Wir erlauben uns, Sie darauf hinzuweisen, dass... (We take the liberty of pointing out that...). The register gap between spoken and formal written German is large."},"examples":[{"german":"Sehr geehrte Damen und Herren, wir erlauben uns, Sie auf die bevorstehende Frist hinzuweisen.","english":"Dear Sir or Madam, we take the liberty of drawing your attention to the upcoming deadline."},{"german":"In Bezug auf Ihr Schreiben vom 15. Oktober möchten wir Ihnen mitteilen, dass Ihre Anfrage bearbeitet wird.","english":"With regard to your letter of 15 October, we would like to inform you that your request is being processed."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can produce formal written German using standard conventions at B2."}}',
'{"items":[{"word":"sich erlauben zu","translation":"to take the liberty of","pronunciation":"zikh er-LOW-ben tsoo","example":"Wir erlauben uns hinzuweisen."},{"word":"hinweisen auf","translation":"to draw attention to/point out","pronunciation":"HIN-vy-zen owf","example":"Auf etwas hinweisen."},{"word":"bevorstehend","translation":"upcoming/imminent","pronunciation":"beh-FOR-shtay-end","example":"Bevorstehende Frist."},{"word":"in Bezug auf","translation":"with regard to","pronunciation":"in beh-TSOOK owf","example":"In Bezug auf Ihr Schreiben."},{"word":"mitteilen","translation":"to inform/communicate","pronunciation":"MIT-ty-len","example":"Wir möchten mitteilen."},{"word":"bearbeiten","translation":"to process/handle","pronunciation":"beh-AR-by-ten","example":"Eine Anfrage bearbeiten."}]}',
'{"title":"Wir erlauben uns, Sie darauf hinzuweisen — formal pointing out","pattern":"Wir erlauben uns, Sie auf + accusative hinzuweisen (to take the liberty of drawing your attention to)","explanation":"Wir erlauben uns, Sie auf X hinzuweisen = We take the liberty of drawing your attention to X. Formal business letter formula. Erlauben uns = take the liberty (polite hedge). Hinweisen auf + accusative = to point to, draw attention to. Hinweisen dass = to point out that. Diese Konstruktion = this construction is elevated and polite — used when flagging something important without sounding blunt. Simpler: Wir möchten Sie darauf aufmerksam machen (We would like to draw your attention to this).","examples":[{"sentence":"Wir erlauben uns, Sie auf die Änderung der AGB hinzuweisen.","translation":"We take the liberty of drawing your attention to the change in terms and conditions."},{"sentence":"Darf ich Sie darauf hinweisen, dass die Frist morgen abläuft?","translation":"May I draw your attention to the fact that the deadline expires tomorrow?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bevorstehend'' means?","options":["upcoming/imminent","forthcoming","pending","approaching"],"correctAnswer":"upcoming/imminent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dear Sir or Madam, we take the liberty of drawing your attention to the upcoming deadline.","options":["Sehr geehrte Damen und Herren, wir erlauben uns, Sie auf die bevorstehende Frist hinzuweisen.","Sehr geehrte Damen und Herren, wir möchten Sie an die Frist erinnern.","Bitte beachten Sie die bevorstehende Frist.","Wir weisen Sie auf die Frist hin."],"correctAnswer":"Sehr geehrte Damen und Herren, wir erlauben uns, Sie auf die bevorstehende Frist hinzuweisen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir erlauben uns, Sie auf die Änderung der AGB ___.","options":["hinzuweisen","hinzuweisen haben","zu hinweisen","hingewiesen haben"],"correctAnswer":"hinzuweisen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: May I draw your attention to the fact that the deadline expires tomorrow","wordBankItems":["Darf","ich","Sie","darauf","hinweisen",",","dass","die","Frist","morgen","abläuft","?"],"correctAnswer":"Darf ich Sie darauf hinweisen , dass die Frist morgen abläuft ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bearbeiten'' in office context means?","options":["to process/handle","to edit","to work on","to deal with"],"correctAnswer":"to process/handle"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000019f',1,'APPROVED','PUBLISHED',
'{"objectives":["Write formal correspondence at B2","Use Korrespondenz formulas","Master formal letter conventions"],"explanation":{"intro":"Formal correspondence at B2 covers the full range of business letter and email conventions.","culturalNote":"German formal correspondence has strict etiquette. Opening: Sehr geehrte Frau Dr. Müller (Dear Dr. Müller — use title). Closing: Mit freundlichen Grüßen (MfG — sincerely), Mit freundlichem Gruß (less formal). Body phrases: Wir teilen Ihnen mit (we inform you), Wir bestätigen den Erhalt Ihres Schreibens (we confirm receipt of your letter), Für Rückfragen stehen wir Ihnen gerne zur Verfügung (we are available for any queries)."},"examples":[{"german":"Wir bestätigen hiermit den Erhalt Ihrer Bewerbung vom 3. Oktober und werden uns innerhalb von zwei Wochen bei Ihnen melden.","english":"We hereby confirm receipt of your application of 3 October and will be in touch with you within two weeks."},{"german":"Für Rückfragen stehen wir Ihnen unter der genannten Telefonnummer jederzeit gerne zur Verfügung.","english":"For any queries, we are always happy to be available to you on the telephone number mentioned."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can write formal business letters and emails in German at B2."}}',
'{"items":[{"word":"bestätigen","translation":"to confirm","pronunciation":"beh-SHTÄT-ee-gen","example":"Bestätigen den Erhalt."},{"word":"hiermit","translation":"hereby","pronunciation":"HEER-mit","example":"Hiermit bestätigen wir."},{"word":"der Erhalt","translation":"receipt","pronunciation":"dayr er-HALT","example":"Erhalt bestätigen."},{"word":"zur Verfügung stehen","translation":"to be available","pronunciation":"tsoor fer-FÜ-goong SHTAY-en","example":"Zur Verfügung stehen."},{"word":"die Rückfrage","translation":"query/follow-up question","pronunciation":"dee RÜK-frah-geh","example":"Für Rückfragen."},{"word":"jederzeit","translation":"at any time/always","pronunciation":"YAY-der-tsyt","example":"Jederzeit erreichbar."}]}',
'{"title":"Zur Verfügung stehen — to be available (formal)","pattern":"jemandem zur Verfügung stehen = to be available to someone (formal business/service formula)","explanation":"Zur Verfügung stehen = to be available (for someone, for a purpose). Wir stehen Ihnen gerne zur Verfügung = We are happy to be available to you. Zur Verfügung stellen = to make available (transitive): Wir stellen Ihnen alle Unterlagen zur Verfügung = We make all documents available to you. Zur Verfügung haben = to have at one''s disposal. This is a key formula in formal German service communication.","examples":[{"sentence":"Das System steht Ihnen rund um die Uhr zur Verfügung.","translation":"The system is available to you around the clock."},{"sentence":"Wir stellen alle benötigten Ressourcen zur Verfügung.","translation":"We make all required resources available."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Hiermit'' means?","options":["hereby","with this","herewith","by this"],"correctAnswer":"hereby"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We hereby confirm receipt of your application of 3 October and will be in touch with you within two weeks.","options":["Wir bestätigen hiermit den Erhalt Ihrer Bewerbung vom 3. Oktober und werden uns innerhalb von zwei Wochen bei Ihnen melden.","Wir haben Ihre Bewerbung erhalten und melden uns bald.","Ihre Bewerbung wurde erfolgreich eingegangen.","Wir bestätigen Ihre Bewerbung und kontaktieren Sie."],"correctAnswer":"Wir bestätigen hiermit den Erhalt Ihrer Bewerbung vom 3. Oktober und werden uns innerhalb von zwei Wochen bei Ihnen melden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System steht Ihnen rund um die Uhr zur ___.","options":["Verfügung","Verfügen","Nutzung","Bereitstellung"],"correctAnswer":"Verfügung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We make all required resources available","wordBankItems":["Wir","stellen","alle","benötigten","Ressourcen","zur","Verfügung","."],"correctAnswer":"Wir stellen alle benötigten Ressourcen zur Verfügung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Jederzeit'' means?","options":["at any time/always","every time","whenever","constantly"],"correctAnswer":"at any time/always"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German literature at B2","Use Literatur vocabulary","Talk about key works and genres"],"explanation":{"intro":"German literature vocabulary at B2 covers major works, literary periods, and analytical vocabulary.","culturalNote":"German literature is vast: Goethe (Faust, Werther), Schiller (Die Räuber, Ode an die Freude), Kafka (Der Prozess, Die Verwandlung), Brecht (Mutter Courage — epic theatre), Thomas Mann (Buddenbrooks, Der Zauberberg), Christa Wolf (Der geteilte Himmel — GDR literature). Nobel laureates: Hesse, Mann, Grass, Jelinek, Müller. Literary periods: Sturm und Drang, Klassik, Romantik, Expressionismus, Gegenwartsliteratur."},"examples":[{"german":"Kafkas Werke lassen sich dem literarischen Expressionismus zuordnen und zeichnen sich durch eine kafkaeske Atmosphäre der Bedrohung und Absurdität aus.","english":"Kafka''s works can be assigned to literary expressionism and are characterised by a Kafkaesque atmosphere of menace and absurdity."},{"german":"Die Epoche der Weimarer Klassik ist durch das Streben nach Humanität, Harmonie und ästhetischer Vollkommenheit geprägt.","english":"The period of Weimar Classicism is characterised by the striving for humanity, harmony and aesthetic perfection."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German literary history, major works, and genres at B2."}}',
'{"items":[{"word":"kafkaesk","translation":"Kafkaesque","pronunciation":"kaf-kah-ESK","example":"Kafkaeske Atmosphäre."},{"word":"geprägt von","translation":"characterised by/shaped by","pronunciation":"geh-PRÄGT fon","example":"Geprägt von."},{"word":"das Streben","translation":"striving/aspiration","pronunciation":"dahs SHTRAY-ben","example":"Streben nach Humanität."},{"word":"zuordnen","translation":"to assign/classify","pronunciation":"TSOO-ord-nen","example":"Einem Genre zuordnen."},{"word":"die Absurdität","translation":"absurdity","pronunciation":"dee ap-zoor-dee-TÄT","example":"Kafkaeske Absurdität."},{"word":"die Epoche","translation":"epoch/period","pronunciation":"dee eh-POH-kheh","example":"Literarische Epoche."}]}',
'{"title":"Geprägt von — characterised/shaped by","pattern":"etwas ist geprägt von + dative = something is characterised/shaped by (Partizip II of prägen)","explanation":"Geprägt von + dative = characterised by, shaped by. Die Epoche ist geprägt von... = The period is characterised by... Prägen = to shape, stamp, characterise. Also: prägen + accusative (active): Die Erfahrungen haben ihn geprägt = The experiences have shaped him. Die Prägung = the shaping, formative influence. Common in literary and historical analysis: geprägt von Widersprüchen (characterised by contradictions), geprägt von Unsicherheit (marked by uncertainty).","examples":[{"sentence":"Das Werk ist geprägt von tiefer Melancholie.","translation":"The work is characterised by deep melancholy."},{"sentence":"Die Nachkriegszeit war geprägt von Wiederaufbau und Hoffnung.","translation":"The post-war era was shaped by reconstruction and hope."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Streben'' means?","options":["striving/aspiration","effort","ambition","pursuit"],"correctAnswer":"striving/aspiration"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The period of Weimar Classicism is characterised by the striving for humanity, harmony and aesthetic perfection.","options":["Die Epoche der Weimarer Klassik ist durch das Streben nach Humanität, Harmonie und ästhetischer Vollkommenheit geprägt.","Die Weimarer Klassik strebt nach Humanität.","Goethe und Schiller prägten die Weimarer Klassik.","Die Klassik ist durch Humanität und Ästhetik bekannt."],"correctAnswer":"Die Epoche der Weimarer Klassik ist durch das Streben nach Humanität, Harmonie und ästhetischer Vollkommenheit geprägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Werk ist geprägt von tiefer ___.","options":["Melancholie","Traurigkeit","Dunkelheit","Schwermut"],"correctAnswer":"Melancholie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The post-war era was shaped by reconstruction and hope","wordBankItems":["Die","Nachkriegszeit","war","geprägt","von","Wiederaufbau","und","Hoffnung","."],"correctAnswer":"Die Nachkriegszeit war geprägt von Wiederaufbau und Hoffnung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kafkaesk'' means?","options":["Kafkaesque","absurd","bureaucratic","nightmarish"],"correctAnswer":"Kafkaesque"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy at B2","Use Philosophie vocabulary","Talk about key philosophical concepts"],"explanation":{"intro":"Philosophy vocabulary at B2 covers key German philosophical traditions and concepts.","culturalNote":"Germany has a rich philosophical tradition: Kant (Kritik der reinen Vernunft — Critique of Pure Reason), Hegel (Dialektik), Marx, Nietzsche (Also sprach Zarathustra — Übermensch), Heidegger (Sein und Zeit), Hannah Arendt (Banalität des Bösen — banality of evil), Habermas (Diskursethik). German Idealism (Idealismus) and Critical Theory (Frankfurter Schule) are globally influential."},"examples":[{"german":"Kants kategorischer Imperativ fordert, dass man nur nach der Maxime handelt, von der man wollen kann, dass sie ein allgemeines Gesetz werde.","english":"Kant''s categorical imperative demands that one act only according to the maxim by which one can will that it become a universal law."},{"german":"Die Frankfurter Schule hinterfragte systematisch gesellschaftliche Verhältnisse, die als selbstverständlich galten.","english":"The Frankfurt School systematically questioned social conditions that were regarded as self-evident."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss major German philosophical concepts and traditions at B2."}}',
'{"items":[{"word":"der kategorische Imperativ","translation":"categorical imperative","pronunciation":"dayr ka-teh-GOH-rish-eh im-peh-rah-TEEF","example":"Kategorischer Imperativ."},{"word":"die Maxime","translation":"maxim","pronunciation":"dee mak-SEE-meh","example":"Nach einer Maxime handeln."},{"word":"hinterfragen","translation":"to question/scrutinise","pronunciation":"HIN-ter-frah-gen","example":"Gesellschaft hinterfragen."},{"word":"selbstverständlich","translation":"self-evident/taken for granted","pronunciation":"ZELPST-fer-shtänt-likh","example":"Als selbstverständlich gelten."},{"word":"die Verhältnisse","translation":"conditions/circumstances","pronunciation":"dee fer-HÄL-nis-eh","example":"Gesellschaftliche Verhältnisse."},{"word":"systematisch","translation":"systematic","pronunciation":"züs-teh-MAH-tish","example":"Systematisch vorgehen."}]}',
'{"title":"Als selbstverständlich gelten — to be taken for granted","pattern":"als selbstverständlich gelten = to be regarded as self-evident, to be taken for granted","explanation":"Als selbstverständlich gelten = to be taken for granted, to be regarded as self-evident. Etw. gilt als selbstverständlich = something is taken for granted. Etw. in Frage stellen = to question something (similar to hinterfragen). Hinterfragen = to question critically, scrutinise (stronger, critical). Das Selbstverständliche hinterfragen = to question what is taken for granted. In philosophy: questioning the Voraussetzungen (premises) that go unquestioned.","examples":[{"sentence":"Was als selbstverständlich gilt, sollte man gelegentlich hinterfragen.","translation":"What is taken for granted should occasionally be questioned."},{"sentence":"Demokratie ist keine Selbstverständlichkeit — sie muss aktiv verteidigt werden.","translation":"Democracy is not a given — it must be actively defended."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Hinterfragen'' means?","options":["to question/scrutinise","to wonder about","to examine","to review"],"correctAnswer":"to question/scrutinise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Frankfurt School systematically questioned social conditions that were regarded as self-evident.","options":["Die Frankfurter Schule hinterfragte systematisch gesellschaftliche Verhältnisse, die als selbstverständlich galten.","Die Frankfurter Schule kritisierte die Gesellschaft.","Gesellschaftliche Bedingungen wurden von der Frankfurter Schule untersucht.","Die Frankfurter Schule analysierte soziale Phänomene."],"correctAnswer":"Die Frankfurter Schule hinterfragte systematisch gesellschaftliche Verhältnisse, die als selbstverständlich galten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Was als selbstverständlich gilt, sollte man gelegentlich ___.","options":["hinterfragen","fragen","überprüfen","infrage stellen"],"correctAnswer":"hinterfragen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Democracy is not a given — it must be actively defended","wordBankItems":["Demokratie","ist","keine","Selbstverständlichkeit","—","sie","muss","aktiv","verteidigt","werden","."],"correctAnswer":"Demokratie ist keine Selbstverständlichkeit — sie muss aktiv verteidigt werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verhältnisse'' means?","options":["conditions/circumstances","relationships","proportions","ratios"],"correctAnswer":"conditions/circumstances"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ethics at B2","Use Ethik vocabulary","Talk about moral philosophy and dilemmas"],"explanation":{"intro":"Ethics vocabulary at B2 covers moral frameworks, dilemmas, and applied ethics.","culturalNote":"Ethik (ethics) is taught in German schools (as an alternative to religion). Applied ethics: Bioethik (bioethics — Ethikrat advises government), Wirtschaftsethik (business ethics), Medienethik. Key concepts: Verantwortungsethik (ethics of responsibility — Max Weber), Gesinnungsethik (ethics of conviction — Weber), Utilitarismus (utilitarianism), Deontologie (deontology — Kant)."},"examples":[{"german":"Ethische Dilemmata entstehen, wenn moralische Werte oder Prinzipien in Konflikt miteinander geraten.","english":"Ethical dilemmas arise when moral values or principles come into conflict with one another."},{"german":"Die Verantwortungsethik bewertet Handlungen nach ihren Konsequenzen, nicht nach der Absicht.","english":"The ethics of responsibility evaluates actions by their consequences, not by intention."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss ethical frameworks, dilemmas, and moral philosophy at B2."}}',
'{"items":[{"word":"das Dilemma","translation":"dilemma","pronunciation":"dahs dee-LEM-ah","example":"Ethisches Dilemma."},{"word":"die Absicht","translation":"intention","pronunciation":"dee AP-zikht","example":"Mit guter Absicht."},{"word":"bewerten","translation":"to evaluate/assess","pronunciation":"beh-VER-ten","example":"Handlungen bewerten."},{"word":"die Konsequenz","translation":"consequence","pronunciation":"dee kon-zeh-KVENTS","example":"Konsequenzen abwägen."},{"word":"geraten in","translation":"to get into/come into","pronunciation":"geh-RAH-ten in","example":"In Konflikt geraten."},{"word":"abwägen","translation":"to weigh up","pronunciation":"AP-vä-gen","example":"Vor- und Nachteile abwägen."}]}',
'{"title":"In Konflikt geraten — to come into conflict (geraten pattern)","pattern":"in + accusative geraten = to get into / come into (of conditions — passive arrival at a state)","explanation":"In Konflikt geraten = to come into conflict. Geraten expresses arriving at a state somewhat passively or involuntarily. In Konflikt geraten mit (to conflict with), in Schwierigkeiten geraten (to get into difficulty), in Panik geraten (to get into panic), in Verlegenheit geraten (to become embarrassed). Pattern: [subject] gerät/geriet in + [accusative noun]. Perfect with sein: ist in Konflikt geraten.","examples":[{"sentence":"Die Interessen der beiden Parteien sind in Konflikt geraten.","translation":"The interests of the two parties have come into conflict."},{"sentence":"Er geriet in ernsthafte Schwierigkeiten.","translation":"He got into serious difficulties."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Abwägen'' means?","options":["to weigh up","to consider","to balance","to deliberate"],"correctAnswer":"to weigh up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Ethical dilemmas arise when moral values or principles come into conflict with one another.","options":["Ethische Dilemmata entstehen, wenn moralische Werte oder Prinzipien in Konflikt miteinander geraten.","Ethische Dilemmata sind Konflikte zwischen Werten.","Wenn Werte kollidieren, entstehen Dilemmata.","Moralische Konflikte sind ethische Dilemmata."],"correctAnswer":"Ethische Dilemmata entstehen, wenn moralische Werte oder Prinzipien in Konflikt miteinander geraten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Interessen der beiden Parteien sind in Konflikt ___.","options":["geraten","kommen","gefallen","gestoßen"],"correctAnswer":"geraten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He got into serious difficulties","wordBankItems":["Er","geriet","in","ernsthafte","Schwierigkeiten","."],"correctAnswer":"Er geriet in ernsthafte Schwierigkeiten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Absicht'' means?","options":["intention","purpose","aim","motive"],"correctAnswer":"intention"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss law at B2","Use Recht vocabulary","Talk about legal system and procedure"],"explanation":{"intro":"Law vocabulary at B2 covers German legal structure, civil and criminal law, and court proceedings.","culturalNote":"Germany has a civil law system (kontinentales Recht). Courts: Amtsgericht (local court), Landgericht (regional court), Oberlandesgericht (higher regional court), Bundesgerichtshof (BGH — Federal Court of Justice). Criminal law: Strafgesetzbuch (StGB). Civil law: Bürgerliches Gesetzbuch (BGB — in force since 1900). EU law has primacy over national law."},"examples":[{"german":"Im deutschen Rechtssystem gilt die Unschuldsvermutung: Jeder gilt als unschuldig, bis seine Schuld bewiesen ist.","english":"In the German legal system, the presumption of innocence applies: everyone is regarded as innocent until their guilt is proven."},{"german":"Das Bürgerliche Gesetzbuch regelt die privatrechtlichen Beziehungen zwischen natürlichen und juristischen Personen.","english":"The Civil Code regulates the private law relations between natural and legal persons."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German law, legal structure, and court proceedings at B2."}}',
'{"items":[{"word":"die Unschuldsvermutung","translation":"presumption of innocence","pronunciation":"dee OON-shoolts-fer-moo-toong","example":"Unschuldsvermutung."},{"word":"die juristische Person","translation":"legal person/entity","pronunciation":"dee yoo-RIS-tish-eh per-ZOHN","example":"Juristische Person."},{"word":"natürlich","translation":"natural (person)","pronunciation":"nah-TÜR-likh","example":"Natürliche Person."},{"word":"privatrechtlich","translation":"private law (adj.)","pronunciation":"pree-VAHT-rekht-likh","example":"Privatrechtliche Beziehung."},{"word":"regeln","translation":"to regulate/govern","pronunciation":"RAY-geln","example":"Rechtliche Verhältnisse regeln."},{"word":"beweisen","translation":"to prove","pronunciation":"beh-VY-zen","example":"Schuld beweisen."}]}',
'{"title":"Gelten als — to be regarded as / to apply (law)","pattern":"etwas gilt als + nominative (to be regarded as) OR ein Gesetz gilt (a law applies/is in force)","explanation":"Gelten als = to be regarded as (without an article): Er gilt als Experte = He is regarded as an expert. Jeder gilt als unschuldig = Everyone is regarded as innocent (presumption of innocence). Also: gelten (without als) = to apply, be in force (of rules and laws): Das Gesetz gilt für alle = The law applies to everyone. Das gilt nicht = That doesn''t apply / count. Unterschied: gelten als = be considered; gelten für = apply to.","examples":[{"sentence":"Diese Regelung gilt ab dem 1. Januar.","translation":"This regulation applies from 1 January."},{"sentence":"Sie gilt als eine der besten Expertinnen auf diesem Gebiet.","translation":"She is regarded as one of the best experts in this field."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Unschuldsvermutung'' means?","options":["presumption of innocence","innocent until proven guilty","assumption of innocence","innocence presumption"],"correctAnswer":"presumption of innocence"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In the German legal system, the presumption of innocence applies: everyone is regarded as innocent until their guilt is proven.","options":["Im deutschen Rechtssystem gilt die Unschuldsvermutung: Jeder gilt als unschuldig, bis seine Schuld bewiesen ist.","In Deutschland gilt man als unschuldig.","Das deutsche Recht schützt Unschuldige.","Die Unschuldsvermutung ist ein Grundprinzip."],"correctAnswer":"Im deutschen Rechtssystem gilt die Unschuldsvermutung: Jeder gilt als unschuldig, bis seine Schuld bewiesen ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Regelung gilt ab dem 1. ___.","options":["Januar","Januar an","Januars","ersten Januar"],"correctAnswer":"Januar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She is regarded as one of the best experts in this field","wordBankItems":["Sie","gilt","als","eine","der","besten","Expertinnen","auf","diesem","Gebiet","."],"correctAnswer":"Sie gilt als eine der besten Expertinnen auf diesem Gebiet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beweisen'' means?","options":["to prove","to show","to demonstrate","to verify"],"correctAnswer":"to prove"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the justice system at B2","Use Justiz vocabulary","Talk about courts and proceedings"],"explanation":{"intro":"Justice system vocabulary at B2 covers courts, judges, procedures, and criminal law.","culturalNote":"Germany''s Justiz (justice system) is independent (richterliche Unabhängigkeit — judicial independence). Key roles: Richter (judge — appointed for life at federal level), Staatsanwalt (public prosecutor), Verteidiger (defence counsel), Schöffe (lay judge — participates in criminal trials). Gerichtsverfahren (court proceedings) are public. The principle of Verhältnismäßigkeit (proportionality) governs sentencing."},"examples":[{"german":"Das Gericht ist an Recht und Gesetz gebunden und urteilt auf der Grundlage der vorgelegten Beweise.","english":"The court is bound by law and statute and judges on the basis of the evidence presented."},{"german":"In einem Rechtsstaat muss die Unabhängigkeit der Justiz von politischen Einflüssen gewährleistet sein.","english":"In a constitutional state, the independence of the judiciary from political influences must be guaranteed."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss courts, judicial independence, and criminal procedure at B2."}}',
'{"items":[{"word":"urteilen","translation":"to judge/give a verdict","pronunciation":"OOR-ty-len","example":"Das Gericht urteilt."},{"word":"vorgelegt","translation":"presented/submitted","pronunciation":"FOR-geh-lehgt","example":"Vorgelegte Beweise."},{"word":"der Rechtsstaat","translation":"constitutional state/rule of law","pronunciation":"dayr REKHTS-shtaht","example":"Rechtsstaat."},{"word":"die Unabhängigkeit","translation":"independence","pronunciation":"dee OON-ap-heng-ikh-kyt","example":"Unabhängigkeit der Justiz."},{"word":"gebunden an","translation":"bound by","pronunciation":"geh-BOON-den an","example":"An Recht gebunden."},{"word":"gewährleisten","translation":"to guarantee/ensure","pronunciation":"geh-VÄR-lys-ten","example":"Unabhängigkeit gewährleisten."}]}',
'{"title":"Gewährleisten — to guarantee/ensure (formal, stronger than sicherstellen)","pattern":"etwas gewährleisten = to guarantee, ensure (formal legal/constitutional language — stronger than sicherstellen)","explanation":"Gewährleisten = to guarantee, ensure (formal, legal). Stronger than sicherstellen (to ensure). Die Verfassung gewährleistet die Grundrechte = The constitution guarantees fundamental rights. Die Gewährleistung = the guarantee (noun). Common in constitutional and legal text. Compare: sicherstellen (to ensure — process-focused), garantieren (to guarantee — can sound more commercial/casual), verbürgen (to vouch for — more personal).","examples":[{"sentence":"Der Staat gewährleistet die Meinungsfreiheit aller Bürger.","translation":"The state guarantees freedom of expression for all citizens."},{"sentence":"Die Qualität der Produkte wird durch strenge Tests gewährleistet.","translation":"The quality of the products is guaranteed through rigorous testing."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Rechtsstaat'' means?","options":["constitutional state/rule of law","legal state","law state","state under law"],"correctAnswer":"constitutional state/rule of law"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In a constitutional state, the independence of the judiciary from political influences must be guaranteed.","options":["In einem Rechtsstaat muss die Unabhängigkeit der Justiz von politischen Einflüssen gewährleistet sein.","Ein Rechtsstaat schützt die Justiz vor Politik.","Die Justiz muss unabhängig von der Politik sein.","Richterliche Unabhängigkeit ist im Rechtsstaat wichtig."],"correctAnswer":"In einem Rechtsstaat muss die Unabhängigkeit der Justiz von politischen Einflüssen gewährleistet sein."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Staat gewährleistet die Meinungsfreiheit aller ___.","options":["Bürger","Staatsbürger","Bevölkerung","Menschen"],"correctAnswer":"Bürger"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The quality of the products is guaranteed through rigorous testing","wordBankItems":["Die","Qualität","der","Produkte","wird","durch","strenge","Tests","gewährleistet","."],"correctAnswer":"Die Qualität der Produkte wird durch strenge Tests gewährleistet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Urteilen'' means?","options":["to judge/give a verdict","to sentence","to rule","to decide"],"correctAnswer":"to judge/give a verdict"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

